import{_ as n,l as i,o as e,c as s,v as r,p as o,x as t,d as E,i as h,S as m}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"执行 RL 与冲击","description":"","frontmatter":{"title":"执行 RL 与冲击","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/rl-execution.md","filePath":"quant/rl-execution.md","lastUpdated":1789023840000}'),d={name:"quant/rl-execution.md"};function A(p,a,B,c,u,_){const l=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="执行-rl-与冲击" tabindex="-1">执行 RL 与冲击 <a class="header-anchor" href="#执行-rl-与冲击" aria-label="Permalink to &quot;执行 RL 与冲击&quot;">​</a></h1><div class="epigraph"><p>最优执行要在波动风险与交易成本之间权衡：交易太快付冲击，交易太慢承担价格对着你的库存随机游走。</p><footer>—— Almgren and Chriss, Optimal Execution of Portfolio Transactions, Journal of Risk, 2000/2001</footer></div><p>方向性 alpha 决定买还是卖；执行决定这一笔在时间与订单类型上如何切开。Bertsimas 与 Lo（1998）把最优执行写成动态规划；Almgren 与 Chriss 给出带临时、永久冲击的可解轨迹。Nevmyvaka、Feng 与 Kearns（2006）把同一问题交给强化学习：状态是剩余量与盘口，动作是现在吃多少。强化学习有吸引力，是因为冲击与填成依赖状态，凸的确定性轨迹管不到队列与涨跌停。危险是把<a href="/quant/sim-to-real-trading">模拟器偏差</a>学成「边缘」。本篇把冲击写成奖励的一部分，说明 RL 相对 Almgren–Chriss 多了什么、在 A 股规则下必须少做什么。它不讨论如何隐藏订单以规避监管，只讨论公开订单类型与公开冲击模型。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>设要在地平线 \\(T\\) 内买入 \\(Q\\) 股。无摩擦时任意轨迹等价。有摩擦时，瞬时吃完付出深度与临时冲击；匀速走完则库存暴露在中间价的布朗风险里。Almgren–Chriss 把成本写成</p> \\[\\mathbb{E}[\\mathrm{cost}]+\\lambda\\,\\mathrm{Var}(\\mathrm{cost}), \\]<p>临时冲击随交易速率上升，永久冲击使中间价沿你的方向漂移。最优轨迹往往前快后慢或相反，取决于风险厌恶与永久冲击是否线性。问题在于真实冲击不是确定性函数：同一速率，在开盘集合竞价、在涨停附近、在北向额度紧张时，深度完全不同。限价单还有不成交风险。于是「速率」这一个动作不够，需要在限价、可立即成交限价、等待之间选择，见<a href="/quant/order-types">订单类型</a>。</p><p>强化学习把盘口形状、剩余时间、剩余量放进状态，让策略条件化。它要解决的不是「有没有冲击」，而是冲击的条件分布是否可学，以及学到的动作是否在交易所规则下可提交。无效价、涨跌停、T+1 可卖量，会把动作空间切成与教科书不同的集合。</p><h3 id="临时冲击、永久冲击与实施缺口" tabindex="-1">临时冲击、永久冲击与实施缺口 <a class="header-anchor" href="#临时冲击、永久冲击与实施缺口" aria-label="Permalink to &quot;临时冲击、永久冲击与实施缺口&quot;">​</a></h3><p>Perold 的实施缺口是决策价到最终成交的差，含延误、部分成交与放弃。Gatheral 要求冲击模型满足无动态套利：你不能通过来回交易从自己的永久冲击里抽钱。线性永久冲击是常见的安全选择；非线性若不当，会在模拟器里出现免费午餐，RL 会拼命去采。临时冲击应在你的成交之后衰减，否则限价提供流动性的奖励被算错。把冲击只写成「成交量 / ADV × 常数」，等于忽略当时<a href="/quant/lob-structure">订单簿</a>的形状与拍卖机制。A 股开盘、收盘集合竞价的冲击与连续竞价不是同一个函数：集合竞价是一次性出清，连续竞价是沿队列消耗。</p><p><span class="marginnote">Kyle 的 \\(\\lambda\\) 是信息被写入价格的斜率，Almgren 的永久冲击是机械的价格位移。两者都叫冲击，识别对象不同。执行模型用的是后者加临时项；把知情交易的 \\(\\lambda\\) 直接当滑点，会把信息效应当成你可以选择的成本。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先写一个可审计的基准：Almgren–Chriss 或 VWAP / POV 一类参与率规则，用自己的成交回报校准临时冲击系数。强化学习只允许在基准之上学习残差：何时比基准更激进、何时改挂限价。状态包括剩余 \\(q\\)、剩余时间、价差、可见深度、队列位置（若有）、是否涨跌停、是否处于不可撤单的集合竞价末段。动作是离散的：市价（或可立即成交限价）吃 \\(x\\)、在某档挂 \\(x\\)、等待、撤单。奖励是负的实施缺口，可加一项库存风险 \\(\\lambda q^2\\sigma^2\\Delta t\\)，与 Almgren–Chriss 的目标对齐，避免智能体为了「平均价格好看」去赌方向。</p><p>训练必须在带冲击的模拟器里，且冲击函数应对智能体自己的量有弹性。离线、只在历史成交上模仿当时的市场，学不到自己的额外量。Nevmyvaka 等人的实验是在真实盘口上做模拟撮合，仍然是模拟；部署前要用小规模真实订单做<a href="/quant/sim-to-real-trading">sim-to-real</a>对照。超参 \\(\\lambda\\)（风险厌恶）应与投资组合层的风险预算一致，而不是在执行 RL 里另找一个让奖励最大的 \\(\\lambda\\)。</p><h3 id="集合竞价与连续竞价要拆成两个策略" tabindex="-1">集合竞价与连续竞价要拆成两个策略 <a class="header-anchor" href="#集合竞价与连续竞价要拆成两个策略" aria-label="Permalink to &quot;集合竞价与连续竞价要拆成两个策略&quot;">​</a></h3><p>开盘 9:15–9:25 是一次性撮合，9:20 后不能撤单，见上交所《交易规则》第 2.4.2、3.3 条。把连续竞价的逐步吃单策略用在开盘，会在不可撤时段留下暴露。方法是：开盘用单独的策略或规则——是否参与集合竞价、报价相对虚拟参考价的偏移——连续时段再用 RL。收盘 14:57–15:00 同理。涨停板上深度是单边的，RL 的「吃对手价」动作无效，应掩码并转为等待或放弃。把全天当同一个 MDP，是在平均两个不同的 \\(P\\)。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>执行 RL 能优于静态轨迹，仅当状态里含有轨迹模型没写的条件信息：某一档突然变薄、队列快速前进、波动上升应加速。机制是状态依赖的速率。若状态只是剩余量与时间，RL 不比把 Hamilton–Jacobi–Bellman 解好多少，却多了过拟合。冲击进入奖励的方式必须让「自己打自己」无利可图：永久冲击提高后续买入成本，智能体才会把量摊开；若模拟器不把永久冲击写回中点，智能体会学会在最后一秒砸全部剩余量。</p><p>逆向选择是限价动作的隐藏项。挂在队里看起来节省了半个价差，若随后价格跳开，你被知情者捡走，实施缺口变差。奖励若只在成交时记账、不成交为零，智能体会过度挂单。正确记账是：不成交留下的剩余量，用后续更差的预期成交价估值，这正是实施缺口的延误项。Cartea、Jaimungal 与 Penalva 的算法交易框架把存货与信息不对称放进连续时间控制；RL 是它的离散、可学习版本，不是可以忽略微观结构的黑箱。</p><p><span class="marginnote">参与率约束（不超过当时成交量的某一比例）是容量与合规常用的硬限制。它应做成动作掩码或对 \\(x\\) 的上界，而不是等惩罚来学。否则智能体在模拟器里会用尖峰把整天的量塞进一分钟。</span></p><h3 id="规模使环境换档" tabindex="-1">规模使环境换档 <a class="header-anchor" href="#规模使环境换档" aria-label="Permalink to &quot;规模使环境换档&quot;">​</a></h3><p>小单的冲击近线性，大单打穿多层，函数凸。在 1% ADV 上训练的策略，在 10% ADV 上不是「同样动作乘十」。Kyle 深度随知情规模变；机械冲击亦然。方法是把目标量相对深度或 ADV 的比值放进状态，并在训练中采样不同 \\(Q\\)。只在一种规模上成功，不能写进容量承诺。A 股小盘与科创板 20% 涨跌幅下，同一参与率对应的价格位移远大于主板 10% 的平均日；分板块校准，不要用全市场一个系数。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>执行 RL 不创造 alpha，只减少既定方向的实施缺口。若信号在执行地平线内衰减很快，最优可能是更激进、更高冲击，净期望仍可能为负——那是 alpha 不够，不是执行没学好。不要用执行智能体去「择时」方向，那会把组合风险偷运进执行层，审计时无法拆开。不要在无涨跌停、可 T+0、无限融券的模拟器里训练，再接到 A 股主机。</p><p>可解释性是执行的约束。经纪商与风控需要速率上限、最差价格、参与率。纯黑箱策略即使模拟器分数高，也难以通过。实务上常见的是：Almgren–Chriss 或 POV 做骨架，RL 或规则只在骨架附近做有界偏离，并且所有偏离可关闭。Obizhaeva 与 Wang 一类限价簿再生模型提供另一组可审计的动态；它们对参数敏感，但比未校准的深度 Q 更容易做压力测试。</p><p><span class="marginnote">冲击校准必须用自己的主动成交，按方向、板块、时段分层。用学术论文里美股大盘的系数给 A 股中小盘做执行，是把别人的深度当成你的深度。</span></p>',26)),(e(),o(m,null,{default:t(()=>[h(l,{id:"mermaid-74",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q0%5B%22%E7%9B%AE%E6%A0%87%E9%87%8F%20Q%20%E4%B8%8E%E6%97%B6%E9%99%90%20T%22%5D%20--%3E%20BENCH%5B%22Almgren-Chriss%20%2F%20POV%20%E5%9F%BA%E5%87%86%22%5D%0A%20%20BOOK%5B%22%E7%9B%98%E5%8F%A3%E4%B8%8E%E6%8B%8D%E5%8D%96%E7%8A%B6%E6%80%81%22%5D%20--%3E%20RL%5B%22%E6%89%A7%E8%A1%8C%E7%AD%96%E7%95%A5%22%5D%0A%20%20BENCH%20--%3E%20RL%0A%20%20RL%20--%3E%20ACT%5B%22%E5%90%83%20%2F%20%E6%8C%82%20%2F%20%E7%AD%89%20%2F%20%E6%92%A4%22%5D%0A%20%20ACT%20--%3E%20IMP%5B%22%E4%B8%B4%E6%97%B6%20%2B%20%E6%B0%B8%E4%B9%85%E5%86%B2%E5%87%BB%22%5D%0A%20%20IMP%20--%3E%20MID%5B%22%E4%B8%AD%E9%97%B4%E4%BB%B7%E6%9B%B4%E6%96%B0%22%5D%0A%20%20MID%20--%3E%20GAP%5B%22%E5%AE%9E%E6%96%BD%E7%BC%BA%E5%8F%A3%22%5D%0A%20%20RULE%5B%22%E6%B6%A8%E8%B7%8C%E5%81%9C%20T%2B1%20%E4%B8%8D%E5%8F%AF%E6%92%A4%E5%8D%95%22%5D%20--%3E%20MASK%5B%22%E5%8A%A8%E4%BD%9C%E6%8E%A9%E7%A0%81%22%5D%0A%20%20MASK%20--%3E%20ACT%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>最优执行权衡冲击与库存风险；Almgren–Chriss 给出可审计的凸基准。</li><li>临时冲击随速率上升并衰减，永久冲击改写后续价格，模型须满足无动态套利直觉。</li><li>RL 仅在状态含轨迹模型没有的条件流动性时有额外价值，且必须在带自身冲击的模拟器里训练。</li><li>开盘/收盘集合竞价与连续竞价是不同的 \\(P\\)，应拆策略并遵守不可撤单时段。</li><li>执行层禁止偷做方向择时；规模相对深度必须进入状态。</li><li>出处：Almgren and Chriss, <em>Journal of Risk</em>, 2000/2001；Bertsimas and Lo, <em>Journal of Financial Markets</em>, 1998；Nevmyvaka, Feng and Kearns, ICML, 2006；Gatheral 对无动态套利冲击的讨论。</li></ul>',2))])}const b=n(d,[["render",A]]);export{D as __pageData,b as default};
